/** Apply a style list merged left to right; returns the merged record for the next diff. */
export function applyStyleList(node: NativeNode, next: Style[], prev: Style | undefined): Style {
  const merged: Style = {};
  for (const style of next) mergeStyle(merged, style);
  applyStyle(node, merged, prev);
  return merged;
}

/** Keep a host element's style in sync with a reactive style record. */
export function bindStyle(node: NativeNode, style: Accessor<Style>): void {
  let previous: Style | undefined = undefined;
  createRenderEffect(() => {
    const next = style();
    applyStyle(node, next, previous);
    previous = next;
  });
}

/** Keep a host element's style in sync with a reactive style list. */
export function bindStyleList(node: NativeNode, styles: Accessor<Style[]>): void {
  let previous: Style | undefined = undefined;
  createRenderEffect(() => {
    previous = applyStyleList(node, styles(), previous);
  });
}

